#ifndef TIO_NEWS_HUB_IDENTITY_POLICY_H
#define TIO_NEWS_HUB_IDENTITY_POLICY_H
#include <stdbool.h>
#include <stddef.h>
#include <string.h>

#if defined(TIO_NEWS_TARGET_BUNDLE_ID) != defined(TIO_NEWS_EXPECTED_ADDON_UUID)
#error "Configure both exact NewsHub target bundle and expected Addon UUID"
#endif
#ifndef TIO_NEWS_TARGET_BUNDLE_ID
#define TIO_NEWS_TARGET_BUNDLE_ID "com.duriea.turboio.research"
#define TIO_NEWS_EXPECTED_ADDON_UUID "3F635A04-D0C3-3196-919E-D4B73D7B0945"
#endif
#define TIO_NEWS_LAB_PREFIX "com.duriea.turboio.manuscriptlab106."
#define TIO_NEWS_LEGACY_LAB_PREFIX "com.duriea.turboio.manuscriptlab105."
#define TIO_NEWS_PREFIX_LENGTH (sizeof(TIO_NEWS_LAB_PREFIX)-1)
#define TIO_NEWS_HAS_LAB_PREFIX (__builtin_strncmp(TIO_NEWS_TARGET_BUNDLE_ID,TIO_NEWS_LAB_PREFIX,TIO_NEWS_PREFIX_LENGTH)==0 || __builtin_strncmp(TIO_NEWS_TARGET_BUNDLE_ID,TIO_NEWS_LEGACY_LAB_PREFIX,TIO_NEWS_PREFIX_LENGTH)==0)
#define TIO_NEWS_BUNDLE_LENGTH (sizeof(TIO_NEWS_TARGET_BUNDLE_ID)-1)
#define TIO_NEWS_UUID_LENGTH (sizeof(TIO_NEWS_EXPECTED_ADDON_UUID)-1)
#define TIO_NEWS_IS_RESEARCH (__builtin_strcmp(TIO_NEWS_TARGET_BUNDLE_ID,"com.duriea.turboio.research")==0)
#define TIO_NEWS_RUN_AT(I) (TIO_NEWS_TARGET_BUNDLE_ID[TIO_NEWS_PREFIX_LENGTH+(I)])
#define TIO_NEWS_RUN_ALNUM(I) ((TIO_NEWS_RUN_AT(I)>='a'&&TIO_NEWS_RUN_AT(I)<='z')||(TIO_NEWS_RUN_AT(I)>='0'&&TIO_NEWS_RUN_AT(I)<='9'))
#define TIO_NEWS_RUN_CHAR(I) ((TIO_NEWS_PREFIX_LENGTH+(I)>=TIO_NEWS_BUNDLE_LENGTH)||TIO_NEWS_RUN_ALNUM(I)||TIO_NEWS_RUN_AT(I)=='-')
#define TIO_NEWS_UUID_HEX(I) ((TIO_NEWS_EXPECTED_ADDON_UUID[I]>='0'&&TIO_NEWS_EXPECTED_ADDON_UUID[I]<='9')||(TIO_NEWS_EXPECTED_ADDON_UUID[I]>='A'&&TIO_NEWS_EXPECTED_ADDON_UUID[I]<='F'))

_Static_assert(sizeof(TIO_NEWS_TARGET_BUNDLE_ID)==__builtin_strlen(TIO_NEWS_TARGET_BUNDLE_ID)+1,"Bundle must be a NUL-free literal");
_Static_assert(sizeof(TIO_NEWS_EXPECTED_ADDON_UUID)==37 && TIO_NEWS_UUID_LENGTH==__builtin_strlen(TIO_NEWS_EXPECTED_ADDON_UUID),"Addon UUID must be canonical uppercase 36-character literal");
_Static_assert(TIO_NEWS_IS_RESEARCH || (TIO_NEWS_HAS_LAB_PREFIX && TIO_NEWS_BUNDLE_LENGTH>=TIO_NEWS_PREFIX_LENGTH+6 && TIO_NEWS_BUNDLE_LENGTH<=TIO_NEWS_PREFIX_LENGTH+40),"Only exact research or isolated lab run bundle is permitted");
_Static_assert(TIO_NEWS_IS_RESEARCH || (TIO_NEWS_RUN_ALNUM(0) && __builtin_strcmp(&TIO_NEWS_TARGET_BUNDLE_ID[TIO_NEWS_PREFIX_LENGTH],"research")!=0 && __builtin_strcmp(&TIO_NEWS_TARGET_BUNDLE_ID[TIO_NEWS_PREFIX_LENGTH],"official")!=0),"Invalid or reserved lab run ID");
_Static_assert(TIO_NEWS_IS_RESEARCH || (TIO_NEWS_RUN_CHAR(0) && TIO_NEWS_RUN_CHAR(1) && TIO_NEWS_RUN_CHAR(2) && TIO_NEWS_RUN_CHAR(3) && TIO_NEWS_RUN_CHAR(4) && TIO_NEWS_RUN_CHAR(5) && TIO_NEWS_RUN_CHAR(6) && TIO_NEWS_RUN_CHAR(7) && TIO_NEWS_RUN_CHAR(8) && TIO_NEWS_RUN_CHAR(9) && TIO_NEWS_RUN_CHAR(10) && TIO_NEWS_RUN_CHAR(11) && TIO_NEWS_RUN_CHAR(12) && TIO_NEWS_RUN_CHAR(13) && TIO_NEWS_RUN_CHAR(14) && TIO_NEWS_RUN_CHAR(15) && TIO_NEWS_RUN_CHAR(16) && TIO_NEWS_RUN_CHAR(17) && TIO_NEWS_RUN_CHAR(18) && TIO_NEWS_RUN_CHAR(19) && TIO_NEWS_RUN_CHAR(20) && TIO_NEWS_RUN_CHAR(21) && TIO_NEWS_RUN_CHAR(22) && TIO_NEWS_RUN_CHAR(23) && TIO_NEWS_RUN_CHAR(24) && TIO_NEWS_RUN_CHAR(25) && TIO_NEWS_RUN_CHAR(26) && TIO_NEWS_RUN_CHAR(27) && TIO_NEWS_RUN_CHAR(28) && TIO_NEWS_RUN_CHAR(29) && TIO_NEWS_RUN_CHAR(30) && TIO_NEWS_RUN_CHAR(31) && TIO_NEWS_RUN_CHAR(32) && TIO_NEWS_RUN_CHAR(33) && TIO_NEWS_RUN_CHAR(34) && TIO_NEWS_RUN_CHAR(35) && TIO_NEWS_RUN_CHAR(36) && TIO_NEWS_RUN_CHAR(37) && TIO_NEWS_RUN_CHAR(38) && TIO_NEWS_RUN_CHAR(39)),"Invalid lab run ID alphabet");
_Static_assert(TIO_NEWS_UUID_HEX(0) && TIO_NEWS_UUID_HEX(1) && TIO_NEWS_UUID_HEX(2) && TIO_NEWS_UUID_HEX(3) && TIO_NEWS_UUID_HEX(4) && TIO_NEWS_UUID_HEX(5) && TIO_NEWS_UUID_HEX(6) && TIO_NEWS_UUID_HEX(7) && TIO_NEWS_EXPECTED_ADDON_UUID[8]=='-' && TIO_NEWS_UUID_HEX(9) && TIO_NEWS_UUID_HEX(10) && TIO_NEWS_UUID_HEX(11) && TIO_NEWS_UUID_HEX(12) && TIO_NEWS_EXPECTED_ADDON_UUID[13]=='-' && TIO_NEWS_UUID_HEX(14) && TIO_NEWS_UUID_HEX(15) && TIO_NEWS_UUID_HEX(16) && TIO_NEWS_UUID_HEX(17) && TIO_NEWS_EXPECTED_ADDON_UUID[18]=='-' && TIO_NEWS_UUID_HEX(19) && TIO_NEWS_UUID_HEX(20) && TIO_NEWS_UUID_HEX(21) && TIO_NEWS_UUID_HEX(22) && TIO_NEWS_EXPECTED_ADDON_UUID[23]=='-' && TIO_NEWS_UUID_HEX(24) && TIO_NEWS_UUID_HEX(25) && TIO_NEWS_UUID_HEX(26) && TIO_NEWS_UUID_HEX(27) && TIO_NEWS_UUID_HEX(28) && TIO_NEWS_UUID_HEX(29) && TIO_NEWS_UUID_HEX(30) && TIO_NEWS_UUID_HEX(31) && TIO_NEWS_UUID_HEX(32) && TIO_NEWS_UUID_HEX(33) && TIO_NEWS_UUID_HEX(34) && TIO_NEWS_UUID_HEX(35),"Addon UUID must be canonical uppercase hex/dashes");

static inline bool TIONewsHubBundleMatches(const char *observed_bundle) {
    return observed_bundle && !strcmp(observed_bundle,TIO_NEWS_TARGET_BUNDLE_ID);
}
static inline bool TIONewsHubAddonMatches(const char *observed_basename,const char *observed_uuid) {
    return observed_basename && observed_uuid && !strcmp(observed_basename,"TurboIOPrivateAddon.dylib") && !strcmp(observed_uuid,TIO_NEWS_EXPECTED_ADDON_UUID);
}
#endif
